    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT ck_price_rule_base CHECK (((base_field)::text = ANY ((ARRAY['COST_PRICE'::character varying, 'RETAIL_PRICE'::character varying, 'WHOLESALE_PRICE'::character varying, 'REPAIR_PRICE'::character varying, 'MIN_PRICE'::character varying, 'CLEARANCE_PRICE'::character varying])::text[]))),
    CONSTRAINT ck_price_rule_flag CHECK (((pricing_flag IS NULL) OR ((pricing_flag)::text = ANY ((ARRAY['NORMAL'::character varying, 'WHOLESALE'::character varying, 'REPAIR'::character varying, 'VIP'::character varying, 'CLEARANCE'::character varying, 'OLD_STOCK'::character varying, 'CUSTOM'::character varying])::text[])))),
    CONSTRAINT ck_price_rule_scope CHECK (((scope_type)::text = ANY ((ARRAY['ALL'::character varying, 'CATEGORY'::character varying, 'BRAND'::character varying, 'PRODUCT'::character varying, 'VARIANT'::character varying])::text[]))),
    CONSTRAINT ck_price_rule_strategy CHECK (((strategy)::text = ANY ((ARRAY['USE_FIELD'::character varying, 'PERCENT_OFF'::character varying, 'AMOUNT_OFF'::character varying, 'MARKUP_ON_COST'::character varying, 'FIXED_PRICE'::character varying])::text[]))),
    CONSTRAINT ck_price_rule_txn CHECK (((transaction_type IS NULL) OR ((transaction_type)::text = ANY ((ARRAY['SALE'::character varying, 'REPAIR'::character varying, 'ESTIMATE'::character varying])::text[]))))
);


